dict(n=90747, t="Gramática de repaso A2", s="Revisar a gramática", city="Montevideo", sc="classroom", rs="school",
 desc="O A2 gira em torno do presente, do pretérito («comí»), do futuro («comeré») e dos pronomes («lo», «la», «le»). Revise com exemplos curtos. Dica: o pronome vem antes do verbo conjugado: «lo compré», não «compré lo».",
 name="Mariana", face="👩🏻", emo=["📚","⏪","⏩","🥘"], mission="Hoje você revisa presente, passado, futuro e pronomes.",
 hook="Ayer comí paella y mañana comeré pescado.|Ontem comi paella e amanhã comerei peixe.", goal="Ayer comí paella y mañana comeré pescado",
 v=[("ayer","ontem","Soa como “a-SHÊR” (no Uruguai, y = “sh” suave).","⏪"),("mañana","amanhã","Soa como “ma-NHA-na”.","⏩"),("comí","comi","Soa como “co-MÍ”.","🍽️"),("comeré","comerei","Soa como “co-me-RÊ”.","🔜"),("lo / la","o / a (pronome)","Soa como “lo / la”.","🔁"),("la rambla","a avenida beira-mar","Soa como “la RRAM-bla”.","🌊")],
 chat=["P: Repasamos tres tiempos. ¿Qué hacés normalmente los lunes? | Revisamos três tempos. O que você faz normalmente às segundas?",
  "Y: Los lunes trabajo por la mañana y estudio por la tarde. | Às segundas trabalho de manhã e estudo à tarde.",
  "P: Muy bien, presente. Ahora, ¿qué hiciste ayer? | Muito bem, presente. Agora, o que você fez ontem?",
  "Y: Ayer comí paella y después caminé por la rambla. | Ontem comi paella e depois caminhei pela rambla.",
  "P: Perfecto, pretérito. ¿Y mañana? | Perfeito, pretérito. E amanhã?",
  "Y: Mañana comeré pescado con mi familia. | Amanhã comerei peixe com minha família.",
  "P: Excelente. Ahora usá un pronombre: ¿compraste el pan? | Excelente. Agora use um pronome: você comprou o pão?",
  "Y: Sí, lo compré en la panadería de la esquina. | Sim, comprei na padaria da esquina.",
  "P: ¿Y le diste el pan a tu hermana? | E você deu o pão à sua irmã?",
  "Y: Sí, le di el pan cuando llegó. | Sim, dei o pão a ela quando chegou.",
  "P: Bárbaro, presente, pasado, futuro y pronombres: todo en orden. | Ótimo, presente, passado, futuro e pronomes: tudo em ordem."],
 tap=[("¿Qué comió ayer?","O que comeu ontem?",["Paella","Pizza","Ensalada"],0,3,"Y: “Ayer comí paella”"),
  ("¿Qué comerá mañana?","O que comerá amanhã?",["Carne","Pescado","Pasta"],1,5,"Y: “comeré pescado con mi familia”"),
  ("¿Dónde compró el pan?","Onde comprou o pão?",["En el mercado","En el supermercado","En la panadería de la esquina"],2,7,"Y: “lo compré en la panadería de la esquina”")],
 swap=("Revisar tempos: presente «como», pretérito «comí», futuro «comeré». 🎓 DELE A2: gramática (tempos e pronomes).",
  [("Ayer…",[("Ayer comí","Ontem comi"),("Ayer compré","Ontem comprei"),("Ayer caminé","Ontem caminhei")],[("paella","paella"),("pan","pão"),("por la rambla","pela rambla")],"."),
   ("Mañana…",[("Mañana comeré","Amanhã comerei"),("Mañana viajaré","Amanhã viajarei"),("Mañana estudiaré","Amanhã estudarei")],[("pescado","peixe"),("a Perú","ao Peru"),("gramática","gramática")],".")]),
 chat2=["Y: Mariana, ¿qué hiciste el fin de semana? | Mariana, o que você fez no fim de semana?",
  "P: El sábado fui a la rambla y compré helado. | No sábado fui à rambla e comprei sorvete.",
  "Y: ¿Y el domingo? | E no domingo?",
  "P: Lo pasé en casa y cociné para mi familia. | Passei em casa e cozinhei para minha família.",
  "Y: ¿Y el próximo fin de semana? | E no próximo fim de semana?",
  "P: Viajaré a Colonia con mis amigas. | Viajarei a Colônia com minhas amigas."],
 slang=("Mariana",["📚","#AE3EC9"],["F: Bo, ¿hiciste los ejercicios de gramática? | Ei, você fez os exercícios de gramática?","Y: Sí, ta, los hice todos, pero me quedaron dudas. | Sim, certo, fiz todos, mas fiquei com dúvidas.","F: Y capaz que te confundiste con el pretérito. | E talvez você tenha se confundido com o pretérito.","Y: Puede ser, igual repasé re bien los pronombres. | Pode ser, mas revisei muito bem os pronomes.","F: Qué bárbaro, vas a aprobar seguro. | Que demais, você vai passar com certeza.","Y: ¡Ojalá! Mañana te cuento cómo me fue. | Tomara! Amanhã te conto como foi."],
  {"bo":"ei, ô (Uruguai)","ta":"certo, tá bom","capaz que":"talvez, pode ser que","re bien":"muito bem","qué bárbaro":"que demais, que incrível"},["capaz que","re bien"]),
 real=("Está bien","Ta bien","na fala, «está» vira «ta» e a resposta curta é simplesmente «ta»"),
 recap_slang="capaz que → talvez, pode ser que"),

